// Root expected fields are observed from actual original Context::default.
use mermaid_rs_renderer::scene::{paint::SpreadMode,prepare::pipeline_context_types::PipelineContext};
#[test]fn actual_source_persistent_context_defaults(){let c=PipelineContext::default();let groups=vec![
 vec![c.current_coverage.to_bits()],vec![match c.sampler.spread_mode{SpreadMode::Pad=>0,SpreadMode::Reflect=>1,SpreadMode::Repeat=>2},c.sampler.inv_width.to_bits(),c.sampler.inv_height.to_bits()],
 c.uniform_color.components.map(f32::to_bits).to_vec(),c.uniform_color.rgba.map(u32::from).to_vec(),c.two_stop.factor.components.map(f32::to_bits).to_vec(),c.two_stop.bias.components.map(f32::to_bits).to_vec(),
 vec![c.gradient.len as u32,c.gradient.factors.len()as u32,c.gradient.biases.len()as u32,c.gradient.t_values.len()as u32],c.gradient.factors.iter().flat_map(|v|v.components.map(f32::to_bits)).collect(),c.gradient.biases.iter().flat_map(|v|v.components.map(f32::to_bits)).collect(),c.gradient.t_values.iter().map(|v|v.get().to_bits()).collect(),
 c.radial_p.map(f32::to_bits).to_vec(),c.radial_mask.to_vec(),[c.limit_x.scale,c.limit_x.inv_scale].map(f32::to_bits).to_vec(),[c.limit_y.scale,c.limit_y.inv_scale].map(f32::to_bits).to_vec(),[c.transform.sx,c.transform.ky,c.transform.kx,c.transform.sy,c.transform.tx,c.transform.ty].map(f32::to_bits).to_vec()];
 let fixture:serde_json::Value=serde_json::from_str(include_str!("fixtures/context-default.json")).unwrap();let expected:Vec<Vec<u32>>=serde_json::from_value(fixture["groups"].clone()).unwrap();assert_eq!(groups.len(),15);for(i,(a,e))in groups.iter().zip(expected).enumerate(){assert_eq!(*a,e,"Source default context group {i}");}println!("15 actual Source default groups / 16 assertions");
}
#[test]fn borrowed_views_observe_original_context_writes(){
 use mermaid_rs_renderer::scene::prepare::{sampling::{HighRegisters,LowRegisters,sample_high_stage,pattern::{PatternContext,SourcePixmap},resources::*},pipeline_control_types::PipelineStage};
 let sampling:serde_json::Value=serde_json::from_str(include_str!("fixtures/sampling.json")).unwrap();let resources:serde_json::Value=serde_json::from_str(include_str!("fixtures/resource-stages.json")).unwrap();
 let bits=|v:&serde_json::Value|->u32{v.as_u64().unwrap().try_into().unwrap()};let channels=|v:&serde_json::Value|->[[u32;8];8]{std::array::from_fn(|c|std::array::from_fn(|l|bits(&v[c][l])))};
 let mut owner=PipelineContext::default();let owner_address=&owner as *const PipelineContext;let mut assertions=0;
 let pixel=[0u8,0,0,255];let source=SourcePixmap::from_bytes(&pixel,1,1).unwrap();let stage=PipelineStage::Mask2PtConicalNan;let mut masks=0;
 for case in sampling["cases"].as_array().unwrap().iter().filter(|c|c["result"][0]==true&&c["input"]["ids"]==serde_json::json!([stage as u8])).take(16){let i=&case["input"];owner.radial_mask=std::array::from_fn(|l|bits(&i["mask"][l]));let mut h=HighRegisters{channels:channels(&i["high"]).map(|v|v.map(f32::from_bits))};sample_high_stage(stage,&mut h,&mut owner,[0,0]).unwrap();
  let expected:&serde_json::Value=&case["result"][2][0];assert_eq!(h.channels.map(|v|v.map(f32::to_bits)),channels(&expected[0]));assert_eq!(owner.radial_mask,std::array::from_fn(|l|bits(&expected[1][l])));assertions+=2;
  {let view=PatternContext{source,pipeline:&owner};assert_eq!(view.pipeline as *const PipelineContext,owner_address);assert_eq!(view.pipeline.radial_mask,owner.radial_mask);assertions+=2;}
  {let mut dst=[];let view=ResourceContext{pipeline:&mut owner,destination:DestinationSurface{data:&mut dst,real_width:0},mask:MaskSurface::default(),aa_mask:AaMask::default()};assert_eq!(view.pipeline as *const PipelineContext,owner_address);assert_eq!(view.pipeline.radial_mask,std::array::from_fn(|l|bits(&expected[1][l])));assertions+=2;}masks+=1;
 }
 assert_eq!(masks,16);assertions+=1;let mut paints=[0usize;2];
 for high in [false,true]{for case in resources["cases"].as_array().unwrap().iter().filter(|c|c["result"][0]==high&&c["input"]["ids"]==serde_json::json!([5])).take(16){let i=&case["input"];let mut dst:Vec<u8>=serde_json::from_value(i["destination"].clone()).unwrap();let mut view=ResourceContext{pipeline:&mut owner,destination:DestinationSurface{data:&mut dst,real_width:i["real_width"].as_u64().unwrap()as usize},mask:MaskSurface::default(),aa_mask:AaMask::default()};
  view.pipeline.uniform_color=UniformColor{components:std::array::from_fn(|l|f32::from_bits(bits(&i["uniform"][l]))),rgba:std::array::from_fn(|l|bits(&i["uniform_bytes"][l])as u16)};view.pipeline.current_coverage=f32::from_bits(bits(&i["coverage"]));assert_eq!(view.pipeline as *const PipelineContext,owner_address);assertions+=1;
  let expected=&case["result"][2][1][0];let cursor=ResourceCursor{dx:3,dy:1,tail:1,program:ResourceProgram::Tail};if high{let mut h=HighRegisters{channels:channels(&i["high"]).map(|v|v.map(f32::from_bits))};resource_high_stage(PipelineStage::UniformColor,&mut h,&mut view,cursor).unwrap();assert_eq!(h.channels.map(|v|v.map(f32::to_bits)),channels(expected));}else{let mut l=LowRegisters{channels:std::array::from_fn(|c|std::array::from_fn(|n|bits(&i["low"][c][n])as u16))};resource_low_stage(PipelineStage::UniformColor,&mut l,&mut view,cursor).unwrap();assert_eq!(l.channels.map(|v|v.map(u32::from)),std::array::from_fn(|c|std::array::from_fn(|n|bits(&expected[c][n]))));}assertions+=1;
  let expected_color=std::array::from_fn(|l|bits(&i["uniform"][l]));let expected_coverage=bits(&i["coverage"]);drop(view);let pattern=PatternContext{source,pipeline:&owner};assert_eq!(pattern.pipeline.uniform_color.components.map(f32::to_bits),expected_color);assert_eq!(pattern.pipeline.current_coverage.to_bits(),expected_coverage);assertions+=2;paints[usize::from(high)]+=1;
 }}assert_eq!(paints,[16,16]);assertions+=1;println!("48 existing actual Source write/read cases / {assertions} shared-owner assertions");
}
